#[ignore]
fn audit_limited_native_pages() {
    let config = Config::from_env();
    let tmp = tempfile::tempdir().unwrap();
    let rows = fixture(config.rows, config.profile);
    let expected = expected_matches(&rows);
    let mut storage = PartitionManager::open(config.storage(tmp.path())).unwrap();
    for batch in rows.chunks(config.batch_rows) { storage.write_batch(batch).unwrap(); }
    storage.checkpoint().unwrap();
    for partition in storage.sealed_partitions().iter().chain(std::iter::once(storage.hot_partition())) {
        if partition.meta.row_count > 0 { IndexBuilder::build_all_indexes(&partition.meta.path).unwrap(); }
    }
    storage.compact_eligible_segments().unwrap();
    assert_native(&storage, &expected);
    for (order, name) in [(logex_storage::native::LogOrder::Ascending,"ascending"),(logex_storage::native::LogOrder::Descending,"descending")] {
        let mut query = filter();
        query.order = order;
        query.limit = Some(1000);
        query.offset = 500;
        let mut oracle = expected.clone();
        if name == "descending" { oracle.reverse(); }
        let oracle: Vec<_> = oracle.into_iter().skip(500).take(1000).collect();
        assert_eq!(oracle.len(),1000);
        for iteration in 0..31 {
            let start = Instant::now();
            let actual = execute_log_filter(&storage,&query).unwrap();
            let elapsed_ms = start.elapsed().as_secs_f64()*1000.0;
            assert_eq!(actual,oracle);
            if iteration != 0 { println!("{}",json!({"kind":"page","order":name,"iteration":iteration,"elapsed_ms":elapsed_ms})); }
        }
    }
}

